MAP
  NAME    "LUFO2026"
  INCLUDE "header.inc"
  WEB
    METADATA
      "ows_title"           "LUFO'S 2026"
      "ows_abstract"        "Luchtfoto's van het grondgebied van de gemeente Amsterdam"
      "ows_onlineresource"  "MAP_URL_REPLACE/tiled/lufo2026"
    END
  END
  CONFIG "CPL_VSIL_CURL_ALLOWED_EXTENSIONS" ".tif,.fgb"
  CONFIG "GDAL_DISABLE_READDIR_ON_OPEN" "TRUE"
  CONFIG "AZURE_STORAGE_ACCOUNT" "stlufoglfdpgoprdweu01"
  CONFIG "AZURE_NO_SIGN_REQUEST" "YES"
  # container overview is nog openbaar; weghalen zodra MapServer een Azure-identity heeft
  #-------------------------------------------------------------------
  # UITVOERFORMATEN
  #-------------------------------------------------------------------
  OUTPUTFORMAT
    NAME      "GTiff"
    DRIVER    "GDAL/GTiff"
    MIMETYPE  "image/tiff"
    IMAGEMODE RGB
    EXTENSION "tif"
  END
  #=============================================================================
  # TILE INDEX: alle levels van de piramide in één FlatGeobuf, filter op "level"
  #=============================================================================
  LAYER
    NAME            "lufo2026-index-5"
    TYPE            POLYGON
    STATUS          OFF
    CONNECTIONTYPE  OGR
    CONNECTION      "/vsiaz/overview/2026/pyramid/imagery-2026.fgb"
    DATA            "imagery-2026"
    FILTER          ( [level] = 5 )
    PROJECTION
      "init=epsg:28992"
    END
    METADATA
      "ows_enable_request"  "!*"
    END
  END
  LAYER
    NAME            "lufo2026-index-4"
